/// Get channel count for a speaker configuration
pub(super) fn get_speaker_config_channels(config: &str) -> Result<usize, String> {
    match config {
        "2.0" => Ok(2),
        "5.0" => Ok(5),
        "5.1" => Ok(6),
        "7.1" => Ok(8),
        "5.1.2" => Ok(8),
        "5.1.4" => Ok(10),
        "7.1.2" => Ok(10),
        "7.1.4" => Ok(12),
        "9.1.4" => Ok(14),
        "9.1.6" => Ok(16),
        _ => Err(format!(
            "Invalid speaker configuration '{}'. Valid options: 2.0, 5.0, 5.1, 7.1, 5.1.2, 5.1.4, 7.1.2, 7.1.4, 9.1.4, 9.1.6",
            config
        )),
    }
}

pub(super) fn list_devices() -> Result<(), String> {
    let msg = "Enumerating audio devices...\n";
    log::info!("{}", msg);
    println!("{}", msg);

    let devices = sotf_audio::devices::get_audio_devices()
        .map_err(|e| format!("Failed to get devices: {}", e))?;

    // Print input devices
    if let Some(input_devices) = devices.get("input") {
        let title = "Input Devices:";
        let separator = "=".repeat(80);
        log::info!("{}", title);
        log::info!("{}", separator);
        println!("{}", title);
        println!("{}", separator);

        for (idx, device) in input_devices.iter().enumerate() {
            let default_marker = if device.is_default { " (Default)" } else { "" };

            if let Some(config) = &device.default_config {
                let rate_range = if device.available_sample_rates.is_empty() {
                    "unknown".to_string()
                } else if device.available_sample_rates.len() == 1 {
                    format!("{} Hz", device.available_sample_rates[0])
                } else {
                    {
                        let rates = &device.available_sample_rates;
                        format!("{}-{} Hz", rates[0], rates[rates.len() - 1])
                    }
                };

                let line = format!(
                    "  [{}] {}{} - {} ch, {} (current: {} Hz), {}",
                    idx + 1,
                    device.name,
                    default_marker,
                    config.channels,
                    rate_range,
                    config.sample_rate,
                    config.sample_format
                );
                log::info!("{}", line);
                println!("{}", line);
            } else {
                let line = format!("  [{}] {}{}", idx + 1, device.name, default_marker);
                log::info!("{}", line);
                println!("{}", line);
            }
        }
        log::info!("");
        println!();
    }

    // Print output devices
    if let Some(output_devices) = devices.get("output") {
        let title = "Output Devices:";
        let separator = "=".repeat(80);
        log::info!("{}", title);
        log::info!("{}", separator);
        println!("{}", title);
        println!("{}", separator);

        for (idx, device) in output_devices.iter().enumerate() {
            let default_marker = if device.is_default { " (Default)" } else { "" };

            if let Some(config) = &device.default_config {
                let rate_range = if device.available_sample_rates.is_empty() {
                    "unknown".to_string()
                } else if device.available_sample_rates.len() == 1 {
                    format!("{} Hz", device.available_sample_rates[0])
                } else {
                    {
                        let rates = &device.available_sample_rates;
                        format!("{}-{} Hz", rates[0], rates[rates.len() - 1])
                    }
                };

                let line = format!(
                    "  [{}] {}{} - {} ch, {} (current: {} Hz), {}",
                    idx + 1,
                    device.name,
                    default_marker,
                    config.channels,
                    rate_range,
                    config.sample_rate,
                    config.sample_format
                );
                log::info!("{}", line);
                println!("{}", line);
            } else {
                let line = format!("  [{}] {}{}", idx + 1, device.name, default_marker);
                log::info!("{}", line);
                println!("{}", line);
            }
        }
        log::info!("");
        println!();
    }

    Ok(())
}
